# COMMENTED EDITION OF v4.0.0: identical model/data algorithms; new source-byte identity.
# DKT + Temporal Affect v4 — one-cell Colab research run
# The embedded ZIP below transports ordinary, inspectable source modules.
# No old DKT/AR-DRAKT cell or checkpoint is required. No held-out test by default.

# A consent switch, not a model hyperparameter. Read the source dataset terms and citation
# guidance before changing it; the cell refuses data loading while False.
ACCEPT_ASSISTMENTS_TERMS = False  # Review official data terms/citation guidance first.
# Only authorizes reuse of this study's own versioned observation cache. PyTorch cache loading
# can deserialize pickle; a filename or checksum is not a security sandbox.
TRUST_OWN_GENERATED_CACHE = True  # ONLY your own v4-generated .pt cache (pickle).
# Set an explicit original CSV when several candidates exist. Do not substitute a compact
# tag/response file: it lacks raw timestamps and affect-validity provenance.
CSV_PATH = ""                   # Blank: locate existing raw CSV under DRAKT/datasets.
# One seed is a development screen. More seeds repeat initialization on fixed student
# membership; this list does not itself turn one selected fold into ten-fold cross-validation.
TRAINING_SEEDS = [42]            # Expand to [42, 43, 44] after inspecting first run.
# True runs raw data, timing, target and partition audits but trains no model. After reviewing
# them, False proceeds to the same scientific experiment; this operational switch is excluded
# from its signature.
PREFLIGHT_ONLY = False           # True: raw validity/timing/eligibility audit, no training.
# Run the packaged CPU synthetic tests before spending GPU time. They test wiring and
# invariants, not educational performance. Disabling them does not alter the fitted-model
# settings.
RUN_SELF_TESTS = True
# Optional pair of readouts masks the DKT state; it tests whether the frozen cognitive encoder
# contributes beyond the engineered input histories.
INCLUDE_NO_DKT_CONTROLS = False  # Adds two paired readouts, not another encoder.
# Remap known student identities into historical memberships rather than reuse stale array
# indices. Unmatched students need an explicit partition decision; renaming folds cannot erase
# prior test exposure.
SPLIT_IDENTITY_PATH = "auto"    # Prefer prior identifiable student membership, not bare indices.
# Use "" only for an explicitly NEW development partition; it does not erase prior exposure.
# Float32 parameters with optional TensorFloat-32 matrix arithmetic. Keep precision fixed for
# matched experiments; no bitwise agreement across GPU/library versions is promised.
PRECISION = "tf32"
# Default features include the current completed problem. A lagged study is separately signed.
# Neither setting verifies how the upstream affect detector generated its scores.
AFFECT_TIMING = "post"          # "lagged" is a separate scientific configuration.
# Window sizes count retained completion-ordered interaction POSITIONS, not days or only
# observed scores. Behavior and affect receive the same operators and widths.
SHORT_WINDOW, LONG_WINDOW = 3, 10
# Bounds raw CSV chunks before local SQLite staging. Final compact student arrays still grow
# with dataset size; this is not a total-memory ceiling.
CSV_CHUNKSIZE = 100_000
# Process-lifetime peak RSS is monitored; a positive budget requests a checked abort, not an
# operating-system memory reservation.
MAX_HOST_RSS_GIB = 0.0           # 0 measures only; a positive value requests abort above limit.
PROJECT_DIR = "/content/drive/MyDrive/DRAKT"
# COMMENTED EDITION: comment bytes change provenance hashes. Use this NEW output folder; keep
# the original source/notebook to resume original v4 checkpoints. Do not bypass a signature
# mismatch.
OUTPUT_DIR = PROJECT_DIR + "/runs/dkt_temporal_affect_v4_commented"
# Temporary SQLite staging and frozen-state banks live on Colab local disk. Losing the runtime
# can require rebuilding these caches, not retraining a completed compatible encoder.
LOCAL_DIR = "/content/dkt_temporal_affect_v4_commented_cache"

from pathlib import Path
import base64, hashlib, io, json, os, stat, subprocess, sys, zipfile
from importlib import metadata

if not ACCEPT_ASSISTMENTS_TERMS:
    raise RuntimeError(
        "Review https://sites.google.com/site/assistmentsdata/datasets/2012-13-school-data-with-affect "
        "and set ACCEPT_ASSISTMENTS_TERMS=True before loading the research data."
    )
# Mount Drive only in the interactive notebook. The child training process reuses the filesystem
# and must not attempt a second interactive authorization.
if not Path("/content/drive/MyDrive").is_dir():
    from google.colab import drive
    drive.mount("/content/drive")

# Retain Colab's CUDA-enabled PyTorch; install only missing/lightweight dependencies.
# Install only missing lightweight packages. Preserve Colab's CUDA-enabled PyTorch and the
# associated runtime rather than replacing it with a CPU wheel.
requirements = {"numpy": "numpy", "pandas": "pandas>=2.0", "scikit-learn": "scikit-learn"}
missing = []
for distribution, requirement in requirements.items():
    try:
        installed = metadata.version(distribution)
        if distribution == "pandas" and int(installed.split(".")[0]) < 2:
            missing.append(requirement)
    except metadata.PackageNotFoundError:
        missing.append(requirement)
if missing:
    subprocess.check_call([sys.executable, "-m", "pip", "install", "-q", *missing])
try:
    import torch
except ImportError as exc:
    raise RuntimeError("Use a Colab Python GPU runtime with its supplied PyTorch installation.") from exc
# Fail clearly before the full training stage when the requested accelerator is absent; do not
# silently run a days-long CPU substitute.
if not torch.cuda.is_available():
    raise RuntimeError("No CUDA GPU found. Select Runtime > Change runtime type > A100 GPU.")
gpu_name = torch.cuda.get_device_name(0)
if "A100" not in gpu_name.upper():
    raise RuntimeError(f"This notebook's locked execution configuration requires an A100; found {gpu_name}.")
print("GPU:", gpu_name)

